    min-height: 100vh;
}

/* Typography */
h1, h2, h3, h4, h5, h6 {
    font-weight: 600;
    letter-spacing: -0.5px;
}

h1 {
    font-size: 3rem;
    margin-bottom: 1rem;
    background: linear-gradient(135deg, #ffffff, #b0b0b0);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
}

h2 {
    font-size: 2rem;
    margin-bottom: 2rem;
    color: #ffffff;
}

h3 {
    font-size: 1.25rem;
    color: #ffffff;
}

a {
    color: #64b5f6;
    text-decoration: none;
    transition: color 0.3s ease;
}

a:hover {
    color: #90caf9;
}

button {
    font-family: inherit;
    cursor: pointer;
}

/* Header Navigation */
header {
    background: rgba(15, 15, 15, 0.95);
    backdrop-filter: blur(10px);
    border-bottom: 1px solid rgba(255, 255, 255, 0.1);
    position: sticky;
    top: 0;
    z-index: 100;
}

.header-content {
    max-width: 1400px;
    margin: 0 auto;
    padding: 1rem 2rem;
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.logo {
    font-size: 1.5rem;
    font-weight: 700;
    background: linear-gradient(135deg, #64b5f6, #42a5f5);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
    letter-spacing: 1px;
}

.nav-menu {
    display: flex;
    gap: 2rem;
    list-style: none;
}

.nav-menu a {
    font-size: 0.95rem;
    color: #b0b0b0;
    transition: color 0.3s ease;
}

.nav-menu a:hover {
    color: #64b5f6;
}

.header-actions {
    display: flex;
    gap: 1.5rem;
    align-items: center;
}

.search-icon, .cart-icon {
    font-size: 1.25rem;
    cursor: pointer;
    color: #b0b0b0;
    transition: color 0.3s ease;
}

.search-icon:hover, .cart-icon:hover {
