+// Form Handler
+function setupFormHandlers() {
+    const forms = document.querySelectorAll('.newsletter-form');
+    forms.forEach(form => {
+        form.addEventListener('submit', (e) => {
+            e.preventDefault();
+            const input = form.querySelector('input[type="email"]');
+            if (input.value) {
+                alert(`Thank you for subscribing with: ${input.value}`);
+                input.value = '';
+            }
+        });
+    });
+    
+    // Add to Cart
+    document.querySelectorAll('.add-to-cart-btn').forEach(btn => {
+        btn.addEventListener('click', () => {
+            const cartBadge = document.querySelector('.cart-badge');
+            const currentCount = parseInt(cartBadge.textContent);
+            cartBadge.textContent = currentCount + 1;
+            cartBadge.setAttribute('aria-label', `Items in cart: ${currentCount + 1}`);
+            alert('Item added to cart!');
+        });
+    });
+    
+    // Shop Deal buttons
+    document.querySelectorAll('.shop-deal-btn').forEach(btn => {
+        btn.addEventListener('click', () => {
+            alert('Navigating to deals...');
+        });
+    });
+    
+    // CTA buttons
+    document.querySelectorAll('.btn-primary, .btn-secondary').forEach(btn => {
+        if (!btn.classList.contains('add-to-cart-btn') && !btn.classList.contains('shop-deal-btn')) {
+            btn.addEventListener('click', () => {
+                alert('Navigating to shop...');
+            });
+        }
+    });
+}
+
+// Accessibility Setup
+function setupAccessibility() {
+    // Make interactive elements keyboard accessible
+    document.querySelectorAll('[role="button"]').forEach(element => {
+        element.addEventListener('keydown', (e) => {
+            if (e.key === 'Enter' || e.key === ' ') {
+                e.preventDefault();
+                element.click();
+            }
+        });
+    });
+    
+    // Add skip to main content link (screen reader only)
+    const skipLink = createElement('a', { 
+        href: '#featured', 
+        className: 'sr-only',
+        'aria-label': 'Skip to main content'
+    }, 'Skip to main content');
+    document.body.insertBefore(skipLink, document.body.firstChild);
+}
